/**
 * Export an Axiomat graph projection as an Atelier `composition.json`.
 *
 * This is the seam the two designs name and that nothing implemented:
 *
 *   atelier docs/design-proof-obligations.md §3 — "model is the workload's
 *   declared structure ... In the MONA-integrated path that is the graph
 *   projection; standalone it is a small composition.json beside targets.json,
 *   so the validators keep running with no backend, which V1 requires."
 *
 * Two jobs live here and nowhere else:
 *
 *   1. `sysmlModelToGraphDocument` — the adapter. The API's
 *      `GET /api/graph/model` returns `SysmlModel { nodes, edges }` where an
 *      edge is `{ relationship, source, target }`; the checks take
 *      `GraphDocument { nodes, relationships }` where a relationship is
 *      `{ type, sourceId, targetId }`. Both shapes are in the repo and they
 *      are not the same shape. Without this function every caller writes its
 *      own eight-line translation, and one of them gets it wrong.
 *
 *   2. THE INTERFACE-KIND MAPPING, and the ids. This is the single boundary
 *      where an authored spelling becomes the spelling Atelier routes on, and
 *      where a graph node's stable id enters the document. Both matter for the
 *      same reason: everything downstream -- a validator that must run on this
 *      part, a verdict that must come back to this exact node -- is keyed on an
 *      id, and `role` (a name) is not one. See interfaceKinds.ts for why the
 *      mapping is a defaults lookup and never a whitelist: an unrecognised kind
 *      is exported verbatim with no channels, because refusing it would make
 *      Axiomat narrower than SysML v2 and would report the resulting silence as
 *      a clean run.
 */

import type { GraphDocument, GraphModelNode, GraphRelationship } from './checks/types.js';
import { resolveInterfaceKind } from './interfaceKinds.js';

/** The edge shape `GET /api/graph/model` actually returns. */
export interface SysmlModelEdge {
  id: string;
  relationship: string;
  source: string;
  target: string;
  name?: string;
  properties?: Record<string, string | number | boolean>;
  createdAt?: string;
  updatedAt?: string;
}

export interface SysmlModelNode {
  id: string;
  type: string;
  name: string;
  qualifiedName?: string;
  text?: string;
  properties?: Record<string, string | number | boolean>;
  createdAt?: string;
  updatedAt?: string;
}

export interface SysmlModel {
  nodes: SysmlModelNode[];
  edges: SysmlModelEdge[];
}

const EPOCH = '1970-01-01T00:00:00.000Z';

/** `GET /api/graph/model` (or a saved copy of it) -> the checks' document. */
export function sysmlModelToGraphDocument(project: { model?: SysmlModel } | SysmlModel): GraphDocument {
  const model = 'model' in project && project.model ? project.model : (project as SysmlModel);
  const nodes: GraphModelNode[] = (model.nodes ?? []).map((n) => ({
    id: n.id,
    kind: 'model_node' as const,
    type: n.type,
    name: n.name,
    qualifiedName: n.qualifiedName,
    text: n.text ?? '',
    properties: n.properties ?? {},
    createdAt: n.createdAt ?? EPOCH,
    updatedAt: n.updatedAt ?? EPOCH,
  }));
  const relationships: GraphRelationship[] = (model.edges ?? []).map((e) => ({
    id: e.id,
    kind: 'relationship' as const,
    type: e.relationship,
    sourceId: e.source,
    targetId: e.target,
    name: e.name,
    properties: e.properties ?? {},
    createdAt: e.createdAt ?? EPOCH,
    updatedAt: e.updatedAt ?? EPOCH,
  }));
  return { nodes, relationships };
}

export interface CompositionConnection {
  /**
   * The graph node's stable id, verbatim.
   *
   * This is what makes a verdict find its way back: Atelier's findings name a
   * subject by this id, and Axiomat attaches them to the node with it. `name`
   * cannot do that job -- it survives neither a rename nor two parts sharing a
   * role name, and a verdict attached to the wrong node is worse than no
   * verdict because it reads as evidence about something.
   */
  id: string;
  name: string;
  /**
   * The kind Atelier routes on, verbatim. A kind this repo has no defaults for
   * is emitted unchanged and simply has no channels -- it is not an error and
   * it is not skipped.
   */
  interface_kind: string;
  channels: Record<string, string>;
  /** Endpoints, so a reader can see what the connection joins. */
  source: string;
  target: string;
}

export interface CompositionPart {
  /**
   * The `PartUsage` node's stable id, verbatim. Same reason as the connection
   * `id` above, and the reason a part's `validated_by` can be an id rather than
   * a role name.
   */
  id: string;
  role: string;
  kind: string;
  artifact: string;
  contract: Record<string, unknown>;
  validated_by?: string[];
  geometry?: {
    placement: { translation: Record<string, number>; rotation: Record<string, number> };
    joints: unknown[];
  };
}

export interface CompositionDocument {
  version: 1;
  composition: {
    name: string;
    parts: CompositionPart[];
    connections: CompositionConnection[];
  };
  /** Parts that own children but have no parent-subject validator (§3.2). */
  unvalidated_parents?: string[];
}

export interface ExportOptions {
  /** Composition name; defaults to the top-level assembly's name. */
  name?: string;
}

const ZERO_PLACEMENT = {
  placement: {
    translation: { x: 0, y: 0, z: 0 },
    rotation: { x: 0, y: 0, z: 0 },
  },
  joints: [],
};

/**
 * Project a graph document into Atelier's `composition.json`.
 *
 * Every part and connection carries its graph node id, and every connection
 * carries its interface kind verbatim. A kind with no defaults gets no channel
 * list; it is not an error, not a warning, and not a skipped connection.
 */
export function exportComposition(
  model: GraphDocument,
  options: ExportOptions = {},
): CompositionDocument {
  const nodeById = new Map(model.nodes.map((n) => [n.id, n]));

  // Axiomat §3.2: every composition relation needs a validator whose subject is
  // the parent. A SubjectMembership edge from a VerificationCaseUsage to a
  // PartUsage is that statement, so the export carries it as `validated_by`
  // and names the parents that have none.
  const validatedSubjects = new Set<string>();
  for (const rel of model.relationships) {
    if (rel.type !== 'SubjectMembership') continue;
    const vc = nodeById.get(rel.sourceId);
    if (vc?.type === 'VerificationCaseUsage') validatedSubjects.add(rel.targetId);
  }

  const ownedBy = new Map<string, string[]>();
  for (const rel of model.relationships) {
    if (rel.type !== 'OwningMembership') continue;
    const owned = ownedBy.get(rel.targetId) ?? [];
    owned.push(rel.sourceId);
    ownedBy.set(rel.targetId, owned);
  }

  const parts: CompositionPart[] = [];
  const unvalidatedParents: string[] = [];

  for (const node of model.nodes) {
    if (node.type !== 'PartUsage') continue;
    const part: CompositionPart = {
      id: node.id,
      role: node.name || node.id,
      kind: str(node.properties?.kind) ?? 'part',
      artifact: str(node.properties?.artifact) ?? '',
      contract: node.text ? { requirement: node.text } : {},
      geometry: { ...ZERO_PLACEMENT, placement: { ...ZERO_PLACEMENT.placement } },
    };
    if (validatedSubjects.has(node.id)) part.validated_by = [node.id];
    else if ((ownedBy.get(node.id) ?? []).length > 0) unvalidatedParents.push(node.name || node.id);
    parts.push(part);
  }

  const connections: CompositionConnection[] = [];
  for (const rel of model.relationships) {
    if (rel.type !== 'ConnectionUsage') continue;
    const raw = rel.properties?.interfaceKind;
    const resolved = resolveInterfaceKind(raw);
    // A malformed kind (absent, empty, not a string) has no spelling to emit,
    // and a connection with no interface kind joins nothing. It is dropped, and
    // the channel-completeness check reports it as an error -- the check owns
    // "this connection is meaningless", the exporter owns "carry what is there".
    if (resolved.kind === 'malformed') continue;
    const channels: Record<string, string> = {};
    for (const [key, value] of Object.entries(rel.properties ?? {})) {
      if (key.startsWith('channel:')) channels[key.slice('channel:'.length)] = String(value);
      else if (key !== 'interfaceKind') channels[key] = String(value);
    }
    connections.push({
      id: rel.id,
      name: rel.name ?? rel.id,
      interface_kind: resolved.value,
      channels,
      source: rel.sourceId,
      target: rel.targetId,
    });
  }

  const doc: CompositionDocument = {
    version: 1,
    composition: {
      name: options.name ?? parts[0]?.role ?? 'composition',
      parts,
      connections,
    },
  };
  if (unvalidatedParents.length > 0) doc.unvalidated_parents = unvalidatedParents;
  return doc;
}

function str(v: unknown): string | undefined {
  return typeof v === 'string' && v !== '' ? v : undefined;
}

