18:     PortDefinition: 'port def', PortUsage: 'port',
19:     ProxyPortUsage: 'proxy port', ProxyPortDefinition: 'proxy port def',
20:     ReferenceDefinition: 'ref def', ReferenceUsage: 'ref',
21:     RequirementDefinition: 'requirement def', RequirementUsage: 'requirement',
22:     ConstraintDefinition: 'constraint def', ConstraintUsage: 'constraint',
23:     AssertConstraintUsage: 'assert',
24:     ActionDefinition: 'action def', ActionUsage: 'action',
25:     StateDefinition: 'state def', StateUsage: 'state',
26:     UseCaseDefinition: 'use case def', UseCaseUsage: 'use case',
27:     CaseDefinition: 'case def', CaseUsage: 'case',
28:     AllocationDefinition: 'allocation def', AllocationUsage: 'allocation',
29:     Comment: 'comment', MetadataFeature: 'metadata',
30:     ConnectionUsage: 'connection', SendActionUsage: 'send', AcceptActionUsage: 'accept',
31:     TransitionUsage: 'transition',
32:   };
33:   return map[type] ?? '';
