anchor="""  it('round-trips: a model authored canonically exports unchanged', () => {"""
new_tests = """  it('exports EVERY node, not only the PartUsages — the empty-composition defect', () => {
    // THE defect this job is named for. `exportComposition` opened with
    // `if (node.type !== 'PartUsage') continue;` — a bare continue with no
    // counter and no warning — so a model built from `ItemUsage`,
    // `ActorUsage` or `StateUsage` exported a composition with NOTHING in
    // `parts[]` and reported success. Before this change both arrays below are
    // empty; see the "fails on the pre-fix code" run quoted in REPORT.md.
    const doc = emptyGraphDocument();
    doc.nodes.push(n({ id: 'i', type: 'ItemUsage', name: 'Fastener' }));
    doc.nodes.push(n({ id: 'a', type: 'ActorUsage', name: 'Operator' }));
    doc.nodes.push(n({ id: 's', type: 'StateUsage', name: 'Charged' }));
    doc.nodes.push(n({ id: 'asm', type: 'PartDefinition', name: 'Assembly' }));

    const parts = exportComposition(doc).composition.parts;
    assert.equal(parts.length, 4, 'every node is projected');
    // ... carrying its own type verbatim, which the old document could not
    // because it only ever held one type.
    assert.deepEqual(parts.map((p) => p.type), ['ItemUsage', 'ActorUsage', 'StateUsage', 'PartDefinition']);
    assert.deepEqual(parts.map((p) => p.kind), ['ItemUsage', 'ActorUsage', 'StateUsage', 'PartDefinition'],
      'kind falls back to the element type rather than a fixed "part"');
    assert.deepEqual(parts.map((p) => p.id), ['i', 'a', 's', 'asm'], 'and each keeps its graph id');
  });

  it('exports EVERY relationship, not only the ConnectionUsages', () => {
    // The same defect on the other array: `if (rel.type !== 'ConnectionUsage')
    // continue;`. A model whose crossings are `SatisfyRequirementUsage` and
    // `AllocationUsage` — the two types the job names — exported zero
    // connections, and the reader could not tell that from a model with no
    // crossings at all.
    const doc = emptyGraphDocument();
    doc.nodes.push(n({ id: 'd', type: 'PartDefinition', name: 'Design' }));
    doc.nodes.push(n({ id: 'req', type: 'RequirementUsage', name: 'ReqMassUnder2kg' }));
    doc.nodes.push(n({ id: 'm', type: 'ItemUsage', name: 'Mass' }));
    doc.relationships.push(r('e1', 'SatisfyRequirementUsage', 'd', 'req', 'mass-under-2kg'));
    doc.relationships.push(r('e2', 'AllocationUsage', 'm', 'd', 'allocates-to'));

    const out = exportComposition(doc);
    assert.equal(out.composition.parts.length, 3);
    const conns = out.composition.connections;
    assert.equal(conns.length, 2, 'both crossings are projected');
    assert.deepEqual(conns.map((c) => c.type), ['SatisfyRequirementUsage', 'AllocationUsage'],
      'the SysML v2 relationship type is carried verbatim');
    assert.deepEqual(conns.map((c) => c.id), ['e1', 'e2']);
    assert.deepEqual(conns.map((c) => c.source), ['d', 'm']);
    assert.deepEqual(conns.map((c) => c.target), ['req', 'd']);
    assert.ok(conns.every((c) => c.interface_kind === undefined),
      'neither declares an interface kind, and that is not a reason to drop either');
  });

  it('a mixed model keeps every node and every relationship, in document order', () => {
    // The whole job in one fixture: parts AND items AND states AND three kinds
    // of crossing, including a legacy `Satisfaction` edge. Nothing is dropped
    // for being an unexpected type.
    const doc = sysmlModelToGraphDocument({
      model: {
        nodes: [
          { id: 'asm', type: 'PartDefinition', name: 'Pump' },
          { id: 'bolt', type: 'ItemUsage', name: 'Bolt' },
          { id: 'op', type: 'ActorUsage', name: 'Technician' },
          { id: 'run', type: 'StateUsage', name: 'Running' },
        ],
        edges: [
          { id: 'om', relationship: 'OwningMembership', source: 'bolt', target: 'asm' },
          { id: 'sat', relationship: 'SatisfyRequirementUsage', source: 'asm', target: 'req-1' },
          { id: 'alloc', relationship: 'AllocationUsage', source: 'bolt', target: 'asm' },
          { id: 'conn', relationship: 'ConnectionUsage', source: 'asm', target: 'op', properties: { interfaceKind: 'mechanical_joint' } },
        ],
      },
    } as never);

    const out = exportComposition(doc);
    assert.equal(out.composition.parts.length, 4);
    assert.equal(out.composition.connections.length, 4, 'membership, satisfaction, allocation and connection alike');
    assert.deepEqual(out.composition.connections.map((c) => c.type), [
      'OwningMembership', 'SatisfyRequirementUsage', 'AllocationUsage', 'ConnectionUsage',
    ]);
    const joint = out.composition.connections.find((c) => c.type === 'ConnectionUsage')!;
    assert.equal(joint.interface_kind, 'mechanical_joint', 'a declared kind is still carried');
    // The membership is containment, not a crossing with channels: it is in the
    // document with no kind, and it is not invented one.
    const membership = out.composition.connections.find((c) => c.type === 'OwningMembership')!;
    assert.equal(membership.interface_kind, undefined);
    // The parent still owns a child and still has no validator naming it.
    assert.deepEqual(out.unvalidated_parents, ['Pump']);
  });

  it('round-trips: a model authored canonically exports unchanged', () => {"""
