/**
 * Validation checks for SysML v2 models.
 *
 * These checks implement the contract binding and composition validation
 * described in docs/design-contracts-and-composition.md §1–§4, §6.
 *
 * Standard library only: uses no external packages beyond Node.js built-ins.
 */

import type { GraphDocument, GraphModelNode, GraphRelationship } from './types.js';
import { resolveInterfaceKind, spellingSuggestion } from '../interfaceKinds.js';

export interface CheckResult {
  name: string;
  passed: boolean;
  findings: Finding[];
}

/**
 * How a connection can fail the \u00a73.1 entailment rule. All three are
 * `error` severity and they differ only in what the author has to go and do:
 *
 *   - `unresolved`  \u2014 an assumption IS stated and no guarantee entails it.
 *                    The author must state a guarantee, or weaken the
 *                    assumption.
 *   - `contradicted` \u2014 an assumption IS stated and a guarantee exists whose
 *                    numeric range excludes it. The two numbers cannot both
 *                    hold; one of them is wrong.
 *   - `unassumed`   \u2014 NO assumption could be extracted from the sink at all.
 *                    There is nothing to compare, so the guarantee is
 *                    unconsumed. The author must state what the sink
 *                    assumes. This is the shape the loop used to skip
 *                    silently: `extractAssumptions` returned [], the body of
 *                    `for (const assumption of targetAssumptions)` never ran,
 *                    and the check reported the connection sound having
 *                    measured nothing.
 */
export type EntailmentFindingType = 'unresolved' | 'contradicted' | 'unassumed';

export interface Finding {
  id: string;
  severity: 'error' | 'warning';
  elementId?: string;
  elementName?: string;
  message: string;
  derivation?: string;
  /** Set by EntailmentCheck; see EntailmentFindingType. Other checks leave it unset. */
  findingType?: EntailmentFindingType;
}

export interface Check {
  name: string;
  claim: string;
  check(model: GraphDocument, params?: Params): CheckResult;
}

export interface Params {
  paramsToml?: Record<string, ParameterEntry>;
  channelDispositions?: Record<string, ChannelDisposition>;
  channelRegistry?: Record<string, string[]>;
}

export interface ParameterEntry {
  value: number | string | boolean;
  unit?: string;
  kind: 'measured' | 'datasheet' | 'assumed';
}

export interface ChannelDis

